from typing import List, Iterable, Optional

# Fix 1 robusto: join con f-strings y list comprehension
def construir_report(items: Iterable[str]) -> str:
    return '\n'.join(f'- {item}' for item in items) + '\n'

# Fix 2: built-ins con key function
def encontrar_usuario_mas_viejo(usuarios: List[dict]) -> Optional[dict]:
    """Encuentra el usuario con mayor edad."""
    if not usuarios:
        return None
    return max(usuarios, key=lambda u: u['edad'])

# Fix 3: truthy + early return
def procesar_si_existe(items: List[str]) -> None:
    if not items:
        print('Lista vacía')
        return
    for item in items:
        print(item)

# Fix 4: precomputar + dict para búsquedas repetidas
class BuscadorUsuarios:
    def __init__(self, usuarios: List[str]):
        # Precomputar lowercase una sola vez: O(n) setup, O(1) búsquedas
        self._index = {u.lower(): u for u in usuarios}

    def buscar(self, nombre: str) -> Optional[str]:
        return self._index.get(nombre.lower())

# Fix 5: any/all con generators
def validar_lista_numeros(lista: List) -> bool:
    """Retorna True si todos son enteros positivos."""
    return (
        isinstance(lista, list) 
        and all(isinstance(x, int) and x > 0 for x in lista)
    )

