simulador.solucion:
def validar_lista(items):
    if not items:
        return False

    # Todos son strings no vacíos
    todos_validos = all(isinstance(x, str) and x for x in items)
    if not todos_validos:
        return False

    # Sin duplicados (comparar len de lista vs set)
    return len(items) == len(set(items))
